const QUESTIONS_V36={"1":[{"q":"No contexto do princípio da insignificância, a consequência dogmática central do reconhecimento da bagatela é:","a":["A exclusão da culpabilidade","A atipicidade material da conduta","A extinção da punibilidade após a condenação","A conversão obrigatória da pena em multa"],"c":1,"e":"O material trata a insignificância como causa de afastamento da tipicidade material; portanto, o fato deixa de ser materialmente típico."},{"q":"Segundo o material, são requisitos objetivos cumulativos tradicionalmente associados à aplicação do princípio da insignificância:","a":["Dolo específico, confissão, primariedade e reparação do dano","Mínima ofensividade, ausência de periculosidade social, reduzido grau de reprovabilidade e inexpressividade da lesão","Primariedade, bons antecedentes, restituição e ausência de vítima","Pequeno valor, arrependimento, confissão e bons antecedentes"],"c":1,"e":"O material reproduz os quatro vetores: mínima ofensividade, nenhuma periculosidade social, reduzido grau de reprovabilidade e inexpressividade da lesão."},{"q":"De acordo com o material, a reincidência ou habitualidade delitiva em matéria de insignificância:","a":["Sempre impede o reconhecimento, sem qualquer exceção","Nunca pode ser considerada","Em regra afasta a insignificância, mas admite análise excepcional das circunstâncias concretas","É irrelevante em qualquer hipótese"],"c":2,"e":"O material registra que a reiteração tende a afastar a insignificância, mas aponta decisões excepcionais quando a lesão é mínima e a ofensividade é reduzidíssima."},{"q":"O princípio da intervenção mínima relaciona-se à ideia de que o Direito Penal deve ser utilizado:","a":["Como primeira resposta estatal para qualquer conflito","Como ultima ratio, quando outros meios de tutela forem insuficientes","Somente em conflitos patrimoniais","Exclusivamente quando houver prisão em flagrante"],"c":1,"e":"O material vincula a intervenção mínima à utilização do Direito Penal como ultima ratio."},{"q":"A culpabilidade, como princípio limitador do Direito Penal, relaciona-se principalmente:","a":["À responsabilidade objetiva por qualquer resultado","À exigência de responsabilização penal pessoal, afastando a punição sem culpabilidade","À possibilidade de punir terceiro pelo fato de outrem","À irrelevância da consciência e da vontade"],"c":1,"e":"A culpabilidade funciona como limite à intervenção penal e é incompatível com a responsabilidade penal objetiva."},{"q":"O princípio da proporcionalidade exige, em síntese, que:","a":["Toda infração receba a mesma pena","A resposta penal mantenha relação adequada com a gravidade da conduta e a proteção do bem jurídico","A pena seja sempre privativa de liberdade","A vítima escolha a sanção aplicável"],"c":1,"e":"A proporcionalidade exige adequação entre a intervenção penal e a gravidade/necessidade da resposta estatal."},{"q":"O princípio da humanidade das penas funciona como limite ao poder punitivo porque:","a":["Permite qualquer pena desde que prevista em lei","Impõe restrições ao conteúdo e à execução das penas incompatíveis com a dignidade humana","Elimina toda possibilidade de prisão","Impede a existência de penas previstas constitucionalmente"],"c":1,"e":"O material inclui a humanidade entre os princípios limitadores das penas e a relaciona à proteção da dignidade."},{"q":"O princípio da confiança, estudado no material, é relacionado à ideia de que:","a":["Todo agente deve desconfiar de qualquer comportamento alheio","No âmbito de uma atuação social organizada, pode-se confiar, dentro de limites, que os demais cumprirão os deveres que lhes incumbem","A confiança elimina a necessidade de cautela em qualquer situação","A confiança substitui a análise do dolo"],"c":1,"e":"A ideia central do princípio da confiança é permitir que, em determinadas relações sociais, o agente confie no comportamento conforme o dever dos demais, dentro dos limites reconhecidos pela teoria."},{"q":"A restituição do bem, isoladamente considerada, é suficiente para reconhecer a insignificância?","a":["Sim, sempre","Não; o material destaca a necessidade de avaliar o conjunto das circunstâncias do caso","Sim, desde que o agente seja reincidente","Somente em crimes praticados com violência"],"c":1,"e":"O material registra que a simples restituição não basta por si só; devem ser avaliados valor, contexto, gravidade e consequências."},{"q":"Em relação aos crimes praticados contra a mulher no âmbito das relações domésticas, o material registra que a insignificância:","a":["É sempre aplicável quando o dano patrimonial for pequeno","Não é admitida segundo o entendimento jurisprudencial indicado no material","Depende apenas da restituição do bem","É obrigatória quando não houver lesão corporal"],"c":1,"e":"O material registra entendimento de inaplicabilidade da insignificância aos crimes/contravenções praticados contra a mulher no âmbito doméstico."}],"2":[{"q":"Segundo o material, o conceito moderno de Constituição pressupõe, entre outros elementos:","a":["Apenas a organização administrativa do Estado","Norma jurídico-política que prevê direitos fundamentais e organiza os poderes políticos","Somente costumes políticos sem força jurídica","Exclusivamente normas econômicas"],"c":1,"e":"O material apresenta o conceito moderno como uma ordenação jurídico-política que contempla direitos fundamentais e organização do poder."},{"q":"Na concepção sociológica de Ferdinand Lassalle, a Constituição é compreendida como:","a":["Norma hipotética fundamental","Decisão política fundamental","Somatória dos fatores reais de poder","Conjunto de princípios morais não escritos"],"c":2,"e":"Para Lassalle, a Constituição corresponde aos fatores reais de poder existentes na sociedade."},{"q":"Na concepção jurídica de Hans Kelsen, a Constituição em sentido lógico-jurídico é:","a":["A Constituição positiva escrita","A norma hipotética fundamental que sustenta o sistema posto","A decisão política do titular do poder constituinte","A soma dos fatores reais de poder"],"c":1,"e":"O material distingue o plano lógico-jurídico, associado à norma fundamental hipotética, do plano jurídico-positivo."},{"q":"Quanto à origem, a Constituição brasileira de 1988 é classificada como:","a":["Outorgada","Cesarista","Pactuada","Promulgada"],"c":3,"e":"O quadro de classificação do material identifica a CF/88 como promulgada/popular."},{"q":"Quanto à alterabilidade, a classificação tradicional da Constituição de 1988 é:","a":["Flexível","Rígida","Imutável","Semirrígida"],"c":1,"e":"O material classifica a CF/88 como rígida, observando que alguns autores a qualificam como super-rígida em razão das cláusulas pétreas."},{"q":"Segundo a classificação de Karl Loewenstein apresentada no material, a Constituição normativa é aquela que:","a":["Serve apenas para legitimar formalmente o poder vigente","Pretende limitar o poder, mas não consegue fazê-lo","É efetivamente observada e consegue disciplinar o processo político","Não possui qualquer pretensão normativa"],"c":2,"e":"Constituição normativa é aquela em que o texto e a realidade política apresentam correspondência e o poder se subordina efetivamente à Constituição."},{"q":"O neoconstitucionalismo, segundo o material, destaca especialmente:","a":["A redução da Constituição a documento político","A concretização dos direitos fundamentais e a força normativa da Constituição","A supremacia absoluta do legislador ordinário","A separação entre Direito e valores"],"c":1,"e":"O material associa o neoconstitucionalismo à eficácia, concretização de direitos fundamentais, força normativa e centralidade da Constituição."},{"q":"Uma norma constitucional de eficácia contida caracteriza-se por:","a":["Não produzir efeitos até regulamentação","Ter aplicabilidade imediata, embora sua abrangência possa ser restringida nos termos admitidos pelo ordenamento","Ser sempre programática","Não possuir força jurídica"],"c":1,"e":"Segundo o material, normas de eficácia contida têm aplicabilidade imediata, mas podem sofrer restrição de seu alcance."},{"q":"Pelo princípio da unidade da Constituição:","a":["Há hierarquia entre normas constitucionais originárias","A Constituição deve ser interpretada como um todo, sem hierarquia entre suas normas constitucionais originárias","Toda colisão constitucional exige declaração de inconstitucionalidade","Normas constitucionais podem ser declaradas inconstitucionais umas em relação às outras"],"c":1,"e":"O material afirma a unidade e indivisibilidade da Constituição e registra a inexistência de hierarquia entre normas constitucionais originárias."},{"q":"Na concordância prática ou harmonização, diante de colisão entre bens constitucionais:","a":["Um direito deve ser sempre eliminado","Deve-se buscar a harmonização, evitando o sacrifício total de um dos direitos","O intérprete deve ignorar o caso concreto","A norma mais antiga sempre prevalece"],"c":1,"e":"A concordância prática busca a harmonização dos direitos em conflito, reduzindo proporcionalmente a restrição e evitando a supressão total de um deles."}],"3":[{"q":"Na classificação das perícias apresentada no material, o exame direto é realizado:","a":["Exclusivamente por meio de testemunhas","Sobre o corpo de delito","Somente sobre documentos médicos","Apenas por reconstrução hipotética"],"c":1,"e":"O material define o exame direto como aquele realizado sobre o corpo de delito, isto é, sobre evidências materiais relacionadas ao crime."},{"q":"O exame indireto pode ser realizado quando:","a":["O corpo de delito está disponível e íntegro","A perícia é necessariamente psiquiátrica","O corpo de delito não está disponível, utilizando-se outras evidências, testemunhos ou vestígios","Não existe qualquer vestígio"],"c":2,"e":"O material explica que o exame indireto utiliza evidências, testemunhas e vestígios quando não é possível examinar diretamente o corpo de delito."},{"q":"Uma perícia médico-legal baseada exclusivamente em prontuários médicos é classificada, segundo o material, como:","a":["Direta","Indireta","Administrativa","Simulada"],"c":1,"e":"O próprio material registra como questão de Delegado SP/2012 que a perícia baseada exclusivamente em prontuários é indireta."},{"q":"A parte objetiva da perícia está relacionada:","a":["À valoração jurídica do juiz","À descrição das alterações visíveis encontradas no exame","À sentença penal","À escolha da pena"],"c":1,"e":"O material distingue a parte objetiva, relacionada às alterações visíveis descritas no laudo, da parte subjetiva, ligada à valoração."},{"q":"A Lei 12.030/2009 assegura, no exercício da perícia oficial de natureza criminal:","a":["Autonomia apenas administrativa","Autonomia técnica, científica e funcional","Subordinação técnica integral ao delegado","Dispensa de concurso público"],"c":1,"e":"O art. 2º da Lei 12.030/2009, reproduzido no material, assegura autonomia técnica, científica e funcional."},{"q":"Segundo o material, são peritos de natureza criminal, observada a legislação específica:","a":["Somente médicos-legistas","Peritos criminais, peritos médico-legistas e peritos odontolegistas, conforme a formação exigida","Somente servidores administrativos","Somente policiais militares"],"c":1,"e":"O art. 5º da Lei 12.030/2009, transcrito no material, contempla essas três categorias."},{"q":"A medicina legal é apresentada no material como:","a":["Somente uma ciência laboratorial","Somente uma arte de elaboração de relatórios","Arte e ciência, exigindo habilidade prática e conhecimento científico","Exclusivamente uma disciplina jurídica"],"c":2,"e":"O material reproduz a concepção de que a medicina legal é simultaneamente arte e ciência."},{"q":"O corpo de delito corresponde, no contexto apresentado, a:","a":["Qualquer opinião de testemunha","Qualquer evidência material da prática do crime","Somente o cadáver","Somente o instrumento do crime"],"c":1,"e":"O material apresenta o corpo de delito como a evidência material relacionada à prática do crime."},{"q":"Quanto à finalidade da perícia, o material destaca que a prova pericial:","a":["Não possui valor probatório","É um dos meios de prova admitidos para formar o convencimento do juiz","Substitui automaticamente a prova testemunhal","Só pode ser utilizada na fase administrativa"],"c":1,"e":"O material afirma expressamente que a prova pericial é um dos meios de prova admitidos em direito."},{"q":"A Lei 12.030/2009 estabelece normas gerais para:","a":["Perícias administrativas em geral","Perícias oficiais de natureza criminal","Somente perícias trabalhistas","Somente perícias previdenciárias"],"c":1,"e":"O art. 1º da Lei 12.030/2009, reproduzido no material, estabelece normas gerais para as perícias oficiais de natureza criminal."}],"4":[{"q":"Segundo o material de Direito Civil, capacidade de direito ou de gozo é:","a":["A aptidão para praticar pessoalmente todos os atos civis","A capacidade genérica para ser sujeito de direitos e deveres","Apenas a capacidade para celebrar contratos","Apenas a capacidade processual"],"c":1,"e":"O material define capacidade de direito como aptidão genérica para ser sujeito de direitos e deveres na ordem privada."},{"q":"Capacidade de fato ou de exercício corresponde à:","a":["Aptidão para ser titular de direitos","Aptidão para pessoalmente praticar atos da vida civil","Personalidade jurídica","Capacidade exclusivamente patrimonial das pessoas jurídicas"],"c":1,"e":"A capacidade de fato é a aptidão para exercer pessoalmente atos da vida civil e se relaciona à teoria das incapacidades."},{"q":"A capacidade civil plena resulta da reunião:","a":["De personalidade e nacionalidade","De capacidade de direito e capacidade de fato","De domicílio e residência","De personalidade e domicílio"],"c":1,"e":"O material apresenta a fórmula: capacidade de direito + capacidade de fato = capacidade civil plena."},{"q":"A emancipação, segundo o material, constitui:","a":["Antecipação da maioridade penal","Antecipação da capacidade de fato, e não da maioridade","Extinção da personalidade","Perda da capacidade de direito"],"c":1,"e":"O material enfatiza que emancipação é antecipação da capacidade de fato, não da maioridade."},{"q":"Na emancipação voluntária, o material destaca que:","a":["Depende sempre de sentença judicial","É ato unilateral dos pais e é irrevogável, ressalvadas as hipóteses de desconstituição por vício","Somente pode ocorrer após os 18 anos","Exige casamento"],"c":1,"e":"O material descreve a emancipação voluntária como decorrente de ato dos pais, com caráter irrevogável, sem prejuízo das hipóteses de desconstituição por vício."},{"q":"Quanto ao domicílio, o elemento que diferencia residência de domicílio é principalmente:","a":["O número de imóveis","O ânimo de permanência e definitividade","A propriedade do imóvel","A existência de contrato de locação"],"c":1,"e":"O material distingue residência e domicílio pelo ânimo de permanência, que confere ao segundo caráter de centro da vida jurídica e social."},{"q":"Segundo o material, o domicílio legal do militar é:","a":["Onde nasceu","Onde possui imóvel próprio","Onde está servindo","Onde foi registrada sua identidade"],"c":2,"e":"O material reproduz a regra de que o domicílio legal do militar é o lugar onde está servindo."},{"q":"A respeito do nascituro, o material apresenta como teorias explicativas:","a":["Somente natalista e positivista","Natalista, personalidade condicional e concepcionista","Somente concepcionista","Somente patrimonialista"],"c":1,"e":"O material apresenta as teorias natalista, da personalidade condicional e concepcionista."},{"q":"Na constitucionalização do Direito Civil, o material destaca:","a":["A separação absoluta entre Constituição e relações privadas","A incidência dos direitos e garantias fundamentais também nas relações privadas","A prevalência automática do Código Civil sobre a Constituição","A eliminação da função social da propriedade"],"c":1,"e":"O material destaca a eficácia dos direitos fundamentais nas relações privadas e a releitura do Direito Civil à luz da Constituição."},{"q":"Na LINDB, a perspectiva pragmática abordada no material relaciona-se, entre outros eixos, a:","a":["Consequencialismo, contextualismo e antifundacionismo","Formalismo, positivismo e abstracionismo","Individualismo, patrimonialismo e legalismo","Irrelevância das consequências da decisão"],"c":0,"e":"O material registra como eixos da perspectiva pragmática o consequencialismo, o contextualismo e o antifundacionismo."}]};
const QUESTIONS=Object.assign({'0':[{"q":"Segundo o material, o aspecto formal do Direito Penal está relacionado a:","a":["Proteção sociológica de valores sem referência à norma","Conjunto de normas que qualifica comportamentos, agentes e sanções","Estudo empírico das causas do crime","Definição de políticas públicas de segurança"],"c":1,"e":"Nas pp. 6–7, o aspecto formal é apresentado a partir do conjunto de normas que disciplina comportamentos, agentes e sanções."},{"q":"A fragmentariedade significa que o Direito Penal:","a":["Protege todos os interesses juridicamente relevantes, sem seleção","Atua apenas depois da ocorrência de um dano civil","Seleciona bens e interesses de especial relevância para receber tutela penal","Pode criar crimes por analogia quando houver lacuna legislativa"],"c":2,"e":"A fragmentariedade expressa a ideia de tutela penal seletiva: nem todo interesse juridicamente relevante recebe proteção por meio do Direito Penal."},{"q":"Um intérprete pretende utilizar analogia para criar uma hipótese de crime que não foi prevista em lei. À luz do princípio da legalidade penal, essa conclusão é:","a":["Admissível, porque a analogia sempre favorece a proteção social","Admissível apenas quando o fato for moralmente reprovável","Inadmissível, porque a analogia não pode servir para criar ou agravar incriminação em prejuízo do acusado","Obrigatória quando houver lacuna no Código Penal"],"c":2,"e":"A legalidade penal impede que a analogia seja utilizada in malam partem para criar crime ou agravar a situação do acusado."},{"q":"Na distinção apresentada no material, assinale a associação correta:","a":["Roxin — proteção abstrata da vigência da norma; Jakobs — proteção exclusiva de bens jurídicos","Roxin — funcionalismo teleológico e proteção de bens jurídicos; Jakobs — funcionalismo sistêmico e proteção da vigência da norma","Roxin — Direito Penal do Inimigo; Jakobs — Direito Penal mínimo","Roxin — Criminologia; Jakobs — Política Criminal"],"c":1,"e":"As pp. 9–12 contrapõem o funcionalismo teleológico de Roxin ao funcionalismo sistêmico de Jakobs."},{"q":"Criminalização secundária corresponde, segundo o material, à:","a":["Seleção e elaboração abstrata dos tipos penais pelo legislador","Atuação concreta das instâncias de controle sobre pessoas e fatos, com destaque para a seletividade","Revogação dos tipos penais existentes","Fixação abstrata das penas em lei"],"c":1,"e":"O material distingue criminalização primária, ligada à produção das normas, e secundária, ligada à atuação concreta das instâncias de controle."},{"q":"Em uma análise orientada pelo Direito Penal do fato, o fundamento da responsabilização deve se concentrar prioritariamente:","a":["Na personalidade e no modo de vida do agente","Na posição social ocupada pelo agente","Na conduta exteriorizada e materializada que constitui o fato relevante","Na periculosidade presumida do indivíduo"],"c":2,"e":"Na p. 15, o material contrapõe Direito Penal do fato e Direito Penal do autor, destacando a centralidade da conduta exteriorizada."},{"q":"No garantismo de Ferrajoli, as garantias primárias podem ser compreendidas, em síntese, como:","a":["Mecanismos posteriores de reparação civil","Limites e vínculos normativos que condicionam o exercício do poder","Somente recursos processuais interpostos após a condenação","Atos administrativos de execução da pena"],"c":1,"e":"As garantias primárias funcionam como limites e vínculos substanciais e formais ao exercício do poder punitivo."},{"q":"Qual alternativa associa corretamente dois axiomas do garantismo penal?","a":["Nullum crimen sine lege — não há crime sem lei; nulla poena sine crimine — não há pena sem crime","Nullum crimen sine lege — não há pena sem crime; nulla poena sine crimine — não há crime sem lei","Nulla actio sine culpa — não há crime sem lei; nulla probatio sine defensione — não há ação sem culpa","Nulla poena sine crimine — não há ação sem culpa; nullum crimen sine lege — não há pena sem crime"],"c":0,"e":"A associação correta é: não há crime sem lei (nullum crimen sine lege) e não há pena sem crime (nulla poena sine crimine)."},{"q":"Segundo o material, o Direito Penal do Inimigo é caracterizado, entre outros aspectos, por:","a":["Punição exclusivamente retrospectiva e preservação integral das garantias","Antecipação/prospecção da punição e relativização ou supressão de garantias","Abolição dos crimes de perigo abstrato","Substituição da pena por medidas exclusivamente civis"],"c":1,"e":"As pp. 18–19 destacam a antecipação da tutela/punição e a flexibilização ou supressão de garantias como características associadas ao modelo."},{"q":"Na teoria das velocidades apresentada no material, a terceira velocidade está associada:","a":["À resposta sem pena privativa de liberdade e preservação integral das garantias","Ao Direito Penal do Inimigo, com flexibilização ou supressão de garantias","Exclusivamente à justiça restaurativa","À eliminação do poder punitivo estatal"],"c":1,"e":"O material associa a terceira velocidade ao Direito Penal do Inimigo e à flexibilização/supressão de garantias."}]}, QUESTIONS_V36);

const QUESTION_LEVELS=['Fundamentação','Fundamentação','Fundamentação','Aplicação','Aplicação','Aplicação','Aplicação','Delegado','Delegado','Delegado'];
const QUESTION_LEVEL_CLASS={'Fundamentação':'easy','Aplicação':'medium','Delegado':'hard'};
for(const _key of Object.keys(QUESTIONS)){QUESTIONS[_key]=QUESTIONS[_key].map((q,idx)=>Object.assign({nivel:QUESTION_LEVELS[idx]||'Aplicação'},q));}

const STORAGE='pcsp_v41';
const LEGACY_STORAGE='pcsp_v3';
function loadDB(){
  const current=JSON.parse(localStorage.getItem(STORAGE)||'null');
  if(current) return current;
  const legacy=JSON.parse(localStorage.getItem(LEGACY_STORAGE)||'null');
  if(legacy){
    localStorage.setItem(STORAGE,JSON.stringify(legacy));
    return legacy;
  }
  return {sessions:[],running:null,checks:{}};
}
const SUBJECTS=['Direito Penal','Direito Constitucional','Direito Civil','Medicina Legal','Revisão'];
const SUBJECT_CLASS={'Direito Penal':'s-penal','Direito Constitucional':'s-const','Direito Civil':'s-civil','Medicina Legal':'s-med','Revisão':'s-rev','Consolidação':'s-rev'};
let db=loadDB();
function saveDB(){localStorage.setItem(STORAGE,JSON.stringify(db))}
function fmt(sec){sec=Math.max(0,Math.floor(sec||0));let h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return [h,m,s].map(v=>String(v).padStart(2,'0')).join(':')}
function dayKey(d){return new Date(d).toISOString().slice(0,10)}
function weekStart(date){let d=new Date(date),day=(d.getDay()+6)%7;d.setHours(0,0,0,0);d.setDate(d.getDate()-day);return d}
function sameWeek(a,b){return weekStart(a).getTime()===weekStart(b).getTime()}
function sameMonth(a,b){let x=new Date(a),y=new Date(b);return x.getFullYear()===y.getFullYear()&&x.getMonth()===y.getMonth()}
function sameYear(a,b){let x=new Date(a),y=new Date(b);return x.getFullYear()===y.getFullYear()}
function sumSeconds(fn){return db.sessions.filter(fn).reduce((a,x)=>a+(x.seconds||0),0)}
function totalFor(subject,period){return sumSeconds(s=>s.subject===subject&&period(s.started,new Date()))}
function totalToday(){return sumSeconds(s=>dayKey(s.started)===dayKey(new Date()))}
function totalThisWeek(){return sumSeconds(s=>sameWeek(s.started,new Date()))}
function totalThisMonth(){return sumSeconds(s=>sameMonth(s.started,new Date()))}
function totalThisYear(){return sumSeconds(s=>sameYear(s.started,new Date()))}
function activeSeconds(){return db.running?Math.floor((Date.now()-db.running.startedAt)/1000):0}
function pct(a,b){return b?Math.min(100,Math.round(a/b*100)):0}
function startTimer(){if(db.running)return;db.running={startedAt:Date.now(),subject:document.getElementById('timerSubject').value,activity:document.getElementById('timerActivity').value};saveDB();renderTimer();tick()}
function stopTimer(){if(!db.running)return;let end=Date.now(),seconds=Math.max(1,Math.floor((end-db.running.startedAt)/1000));db.sessions.push({started:new Date(db.running.startedAt).toISOString(),ended:new Date(end).toISOString(),seconds,subject:db.running.subject,activity:db.running.activity});db.running=null;saveDB();renderTimer()}
function cancelTimer(){db.running=null;saveDB();renderTimer()}
function tick(){if(!db.running)return;let el=document.getElementById('timerDisplay');if(el)el.textContent=fmt(activeSeconds());setTimeout(tick,1000)}
function check(id){return `<label class="check"><input type="checkbox" data-check="${id}" ${db.checks[id]?'checked':''}> Concluído</label>`}
function bindChecks(){document.querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{db.checks[e.dataset.check]=e.checked;saveDB()})}
function wrap(x){return `<div class="container">${x}<p class="foot">Semana 01 é o modelo estrutural das 48 semanas. Cronômetro livre, sem Pomodoro. Arquitetura ${BUILD_VERSION}.</p></div>`}
function dashboard(){let target=18*3600,tw=totalThisWeek(),rows=SUBJECTS.map(s=>({subject:s,seconds:totalFor(s,sameWeek)})),max=Math.max(1,...rows.map(x=>x.seconds));return wrap(`<div class="hero"><span class="tag">SEMANA 01 / 48</span><h2>Painel de hoje</h2><p class="muted">O cronômetro registra o tempo real estudado.</p><div class="statgrid"><div class="stat"><strong>Hoje</strong><b>${fmt(totalToday())}</b></div><div class="stat"><strong>Semana</strong><b>${fmt(tw)}</b></div><div class="stat"><strong>Mês</strong><b>${fmt(totalThisMonth())}</b></div><div class="stat"><strong>Ano</strong><b>${fmt(totalThisYear())}</b></div></div></div><div class="card"><h3>Meta semanal inicial</h3><p class="muted">18 horas líquidas como parâmetro de trabalho, ajustável à sua realidade.</p><div class="progress"><i style="width:${pct(tw,target)}%"></i></div><p><strong>${fmt(tw)}</strong> de 18:00:00 — ${pct(tw,target)}%</p></div><div class="card"><h3>Horas por disciplina — semana atual</h3>${rows.map(x=>`<div class="subject-row"><span>${x.subject}</span><div class="subject-bar"><i class="${SUBJECT_CLASS[x.subject]}" style="width:${Math.round(x.seconds/max*100)}%"></i></div><b>${fmt(x.seconds)}</b></div>`).join('')}</div><div class="grid">${W.slice(0,6).map((x,i)=>`<div class="card day" onclick="day(${i})"><span class="tag">${x.d}</span><span class="tag">${x.time}</span><h3>${x.s}</h3><p>${x.t}</p><small>PDF: ${x.pg}</small></div>`).join('')}</div>`)}
function renderTimer(){let r=db.running;document.getElementById('content').innerHTML=wrap(`<div class="hero"><h2>⏱ Cronômetro de estudos</h2><p class="muted">Cronômetro livre. Não usamos Pomodoro.</p><div class="timer-box" id="timerDisplay">${fmt(activeSeconds())}</div><div class="timer-meta"><select id="timerSubject">${SUBJECTS.map(s=>`<option ${r&&r.subject===s?'selected':''}>${s}</option>`).join('')}</select><select id="timerActivity"><option>PDF</option><option>Vídeo</option><option>Lei seca</option><option>Jurisprudência</option><option>Doutrina</option><option>Questões</option><option>Revisão</option><option>Estudo</option></select></div><div style="margin-top:12px">${r?'<button class="btn" onclick="stopTimer()">Finalizar e registrar</button><button class="btn danger" onclick="cancelTimer()">Cancelar</button>':'<button class="btn" onclick="startTimer()">Iniciar estudo</button>'}</div></div><div class="notice"><strong>Registro:</strong> ao finalizar, a sessão entra no histórico com disciplina, atividade, início, término e duração. Atualizar a página não interrompe a sessão.</div>`);if(r)tick()}
function renderHistory(){let rows=[...db.sessions].sort((a,b)=>new Date(b.started)-new Date(a.started)).map(s=>`<tr><td>${new Date(s.started).toLocaleDateString('pt-BR')}</td><td>${new Date(s.started).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}–${new Date(s.ended).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</td><td>${s.subject}</td><td>${s.activity}</td><td><strong>${fmt(s.seconds)}</strong></td></tr>`).join('');document.getElementById('content').innerHTML=wrap(`<div class="hero"><h2>Histórico de estudos</h2><p class="muted">Hoje, semana, mês e ano são calculados a partir das sessões registradas.</p></div><table class="table"><tr><th>Data</th><th>Horário</th><th>Disciplina</th><th>Atividade</th><th>Tempo</th></tr>${rows||'<tr><td colspan="5">Nenhuma sessão registrada.</td></tr>'}</table><div class="card" style="margin-top:16px"><button class="btn danger" onclick="clearHistory()">Apagar histórico de tempo</button></div>`)}
function clearHistory(){if(confirm('Apagar todo o histórico de tempo?')){db.sessions=[];saveDB();renderHistory()}}
function perf(){let total=totalThisYear(),answered=Object.keys(db.checks).filter(k=>/^q\d+_\d+$/.test(k)).length,correct=Object.keys(db.checks).filter(k=>/^q\d+_\d+$/.test(k)&&db.checks[k]).length;return wrap(`<div class="hero"><h2>Desempenho</h2><div class="statgrid"><div class="stat"><strong>Horas no ano</strong><b>${fmt(total)}</b></div><div class="stat"><strong>Questões respondidas</strong><b>${answered}</b></div><div class="stat"><strong>Acertos</strong><b>${correct}</b></div></div></div><div class="card"><h3>Distribuição anual por disciplina</h3>${SUBJECTS.map(s=>{let sec=totalFor(s,sameYear);return `<div class="subject-row"><span>${s}</span><div class="subject-bar"><i class="${SUBJECT_CLASS[s]}" style="width:${total?Math.round(sec/total*100):0}%"></i></div><b>${fmt(sec)}</b></div>`}).join('')}</div>`)}
function searchPage(){return wrap(`<div class="hero"><h2>🔎 Central de Pesquisa</h2><p class="muted">Digite um tema e escolha a fonte. A Central direciona a pesquisa; a análise jurídica continua sendo feita com conferência das fontes.</p><div class="search-grid"><input class="searchbox" id="globalQuery" placeholder="Ex.: princípio da insignificância"><select id="globalSource"><option value="google">Google</option><option value="youtube">YouTube</option><option value="dd">Dizer o Direito</option><option value="scholar">Google Scholar</option><option value="stj">STJ</option><option value="stf">STF</option><option value="planalto">Planalto</option></select></div><div style="margin-top:10px"><button class="btn" onclick="doSearch()">Pesquisar</button><button class="btn alt" onclick="askJohn()">Preparar pergunta para o John</button></div></div><div class="card"><h3>Fontes jurídicas</h3><a class="btn alt" target="_blank" href="https://www.stj.jus.br/sites/portalp/Inicio">STJ</a><a class="btn alt" target="_blank" href="https://portal.stf.jus.br/">STF</a><a class="btn alt" target="_blank" href="https://www.planalto.gov.br/">Planalto</a><a class="btn alt" target="_blank" href="https://buscadordizerodireito.com.br/">Dizer o Direito</a><a class="btn alt" target="_blank" href="https://scholar.google.com/">Google Scholar</a></div><div class="card"><h3>🤖 Preparar pesquisa com o John</h3><p class="muted">A versão estática não deve guardar uma chave de IA no navegador. Em vez disso, prepare uma pergunta completa, copie e traga para esta conversa.</p><textarea id="johnPrompt" class="searchbox" rows="6" placeholder="Digite sua dúvida jurídica..."></textarea><br><button class="btn" onclick="copyPrompt()">Copiar pergunta</button></div>`)}
function doSearch(){let q=document.getElementById('globalQuery').value.trim(),src=document.getElementById('globalSource').value;if(!q)return;let u;if(src==='google')u='https://www.google.com/search?q='+encodeURIComponent(q);if(src==='youtube')u='https://www.youtube.com/results?search_query='+encodeURIComponent(q);if(src==='dd')u=dLink(q);if(src==='scholar')u='https://scholar.google.com/scholar?q='+encodeURIComponent(q);if(src==='stj')u='https://www.google.com/search?q='+encodeURIComponent('site:stj.jus.br '+q);if(src==='stf')u='https://www.google.com/search?q='+encodeURIComponent('site:stf.jus.br '+q);if(src==='planalto')u='https://www.google.com/search?q='+encodeURIComponent('site:planalto.gov.br '+q);window.open(u,'_blank')}
function askJohn(){let q=document.getElementById('globalQuery').value.trim();document.getElementById('johnPrompt').value=`Atue como meu curador jurídico para o concurso de Delegado da Polícia Civil de São Paulo. Tema: ${q||'[digite o tema]'}. Considere legislação vigente, jurisprudência recente de STF/STJ, doutrina relevante, perfil de Delegado PC-SP e fontes oficiais. Diferencie conteúdo-base de atualização e não invente referências.`}
function copyPrompt(){let t=document.getElementById('johnPrompt');t.select();document.execCommand('copy');alert('Pergunta copiada. Cole-a nesta conversa para eu realizar a pesquisa e a curadoria.')}
function week(){return wrap(`<div class="hero"><h2>Semana 01 / 48</h2><p class="muted">Semana 01 é o modelo estrutural das 48 semanas.</p><div class="notice">Padrão: Vídeo Delta → vídeo complementar validado → PDF com páginas → lei seca → jurisprudência por subtema → doutrina → questões → revisão → controle de tempo. Sem Pomodoro.</div></div><table class="table"><tr><th>Dia</th><th>Disciplina</th><th>Tema</th><th>Tempo</th><th>Páginas</th></tr>${W.map((x,i)=>`<tr><td><button class="btn alt" onclick="day(${i})">${x.d}</button></td><td>${x.s}</td><td>${x.t}</td><td>${x.time}</td><td>${x.pg}</td></tr>`).join('')}</table>`)}
function day(i){let x=W[i],v=VIDEOS[i]||{};document.getElementById('content').innerHTML=wrap(`<button class="btn alt" onclick="show('week')">← Semana 01</button><div class="hero"><span class="tag">${x.d}</span><h2>${x.s}</h2><p class="muted">${x.t} · ${x.time}</p><div class="notice"><strong>Controle de tempo:</strong> use o Cronômetro e selecione disciplina + atividade.</div></div><div class="card"><h3>1. Vídeos de estudo</h3>${v.delta?`<div class="source"><strong>${v.delta.kind}</strong><br>${v.delta.title}<br><span class="tag">${v.delta.status||FRESH.base}</span></div><a class="btn" target="_blank" href="${v.delta.url}">▶ Abrir Delta</a>`:''}${v.delta2?`<div class="source"><strong>${v.delta2.kind}</strong><br>${v.delta2.title}<br><span class="tag">${v.delta2.status||FRESH.base}</span></div><a class="btn alt" target="_blank" href="${v.delta2.url}">📖 Abrir material Delta</a>`:''}${v.ceisc?`<div class="source"><strong>${v.ceisc.kind}</strong><br>${v.ceisc.title}<br><span class="tag">${v.ceisc.status||FRESH.base}</span></div><a class="btn alt" target="_blank" href="${v.ceisc.url}">▶ Abrir CEISC</a>`:''}${i<=4?`<div class="source"><strong>Pesquisa audiovisual temática</strong><br>Se não houver vídeo individual validado, a Central não aponta para o canal; pesquisa o tema exato.</div><a class="btn alt" target="_blank" href="${ytSearch(x.t)}">Pesquisar no YouTube pelo tema</a>`:''}<p class="muted small">${v.note||'Use vídeos apenas para esclarecer ou reforçar lacunas.'}</p>${check(i+'v')}</div><div class="card"><h3>Roteiro de execução — 3h</h3><div class="source"><strong>Distribuição sugerida:</strong> vídeo 30 min · PDF 45 min · lei seca 20 min · jurisprudência 20 min · doutrina 15 min · questões 35 min · revisão ativa 15 min. Use o cronômetro por atividade; a distribuição é um parâmetro, não uma obrigação rígida.</div>${check(i+'plan')}</div><div class="card"><h3>2. PDF Delta — leitura orientada</h3><div class="source"><strong>Arquivo:</strong> ${x.pdf}<br><strong>Páginas:</strong> ${x.pg}</div><ul>${x.topics.map(z=>`<li>${z}</li>`).join('')}</ul>${check(i+'p')}</div><div class="card"><h3>3. Lei seca — fonte oficial</h3><p>${x.law}</p>${i===0?`<a class="btn" target="_blank" href="${LAW[i].url}">⚖ Abrir Constituição — art. 5º e art. 22, I</a><a class="btn alt" target="_blank" href="${LAW[i].cp}">⚖ Abrir Código Penal — arts. 1º–3º</a>`:`<a class="btn" target="_blank" href="${LAW[i].url}">⚖ Abrir legislação</a>`}${i===4?`<a class="btn alt" target="_blank" href="${LAW[i].lindb}">⚖ LINDB</a>`:''}${check(i+'l')}</div><div class="card"><h3>4. Jurisprudência — pesquisa por subtema</h3><p class="muted">Use os botões específicos. Depois confira os julgados relevantes na fonte oficial e registre tese, tribunal, data e impacto para Delegado.</p><div>${x.jsearch.map(q=>`<a class="btn" target="_blank" href="${dLink(q)}">🔎 ${q}</a>`).join('')}</div>${CURRENT_SOURCES[i]?`<h4>Jurisprudência atual — fontes selecionadas</h4><div>${CURRENT_SOURCES[i].dd.map(s=>`<a class="btn alt" target="_blank" href="${s.url}">Dizer o Direito — ${s.title.replace('Dizer o Direito — ','')}</a>`).join('')}</div><div>${CURRENT_SOURCES[i].official.map(s=>`<a class="btn alt" target="_blank" href="${s.url}">⚖ ${s.title}</a>`).join('')}</div>`:''}${check(i+'j')}</div><div class="card"><h3>5. Doutrina — pesquisa direcionada</h3><p class="muted">Pesquisa separada da jurisprudência; use Google Scholar para localizar artigos e trabalhos acadêmicos pertinentes.</p><div>${x.dsearch.map(q=>`<a class="btn alt" target="_blank" href="${gLink(q)}">📚 ${q}</a>`).join('')}</div>${CURRENT_SOURCES[i]?`<h4>Leituras selecionadas</h4><div>${CURRENT_SOURCES[i].doctrine.map(s=>`<a class="btn alt" target="_blank" href="${s.url}">📚 ${s.title}</a>`).join('')}</div>`:''}${check(i+'d')}</div><div class="card"><h3>6. Atualidade e conferência</h3><p><strong>Verificação da arquitetura:</strong> 23/08/2026. Conteúdo-base não é tratado como atualização.</p><a class="btn alt" target="_blank" href="https://scon.stj.jus.br/jurisprudencia/externo/informativo/">⚖ Informativos STJ</a>${check(i+'a')}</div><div class="card"><h3>7. Questões — progressão de dificuldade</h3><p>${QUESTIONS[i]?`${QUESTIONS[i].length} questões autorais, distribuídas progressivamente: 3 de Fundamentação, 4 de Aplicação e 3 no nível Delegado. Resolva sem consulta e confira somente depois.`:`Questões personalizadas ainda não cadastradas para esta sessão. Não considerar este bloco como concluído.`}</p>${QUESTIONS[i]?`<div class="notice">Sequência: <strong>Fundamentação → Aplicação → Delegado</strong>. O nível indica a exigência cognitiva esperada, não apenas a quantidade de conteúdo.</div><div id="quiz">${QUESTIONS[i].map((qq,n)=>`<div class="source"><div><span class="badge qlevel ${QUESTION_LEVEL_CLASS[qq.nivel]||'medium'}">${qq.nivel||'Aplicação'}</span></div><strong>${n+1}. ${qq.q}</strong>${qq.a.map((a,k)=>`<label class="check"><input type="radio" name="q${n}" value="${k}"> ${String.fromCharCode(65+k)}) ${a}</label>`).join('')}<button class="btn alt" onclick="answer(${n},${i})">Conferir</button><div id="exp${n}" class="small"></div></div>`).join('')}<div class="notice">Meta: responder primeiro de memória. Depois da correção, registre no caderno de erros os itens errados ou com dúvida.</div>`:`<p>${x.q} conforme a plataforma/matriz de questões.</p>`}${check(i+'q')}</div><div class="card"><h3>8. Revisão</h3><p><strong>48–72h:</strong> recuperação ativa sem releitura integral. Refaça as questões erradas, explique em voz alta os conceitos centrais e consulte novamente apenas os pontos de dúvida. Depois, retome o tema conforme o calendário cumulativo.</p>${check(i+'r')}</div>`);bindChecks();scrollTo(0,0)}
function juris(){return wrap(`<div class="hero"><h2>Jurisprudência</h2><p class="muted">Use os links por subtema dentro de cada sessão. Para atualização, confronte com STF/STJ.</p><a class="btn alt" target="_blank" href="https://scon.stj.jus.br/jurisprudencia/externo/informativo/">⚖ STJ — Informativos</a></div><div class="notice">Uma pesquisa funcional não é automaticamente uma pesquisa adequada. O objetivo é reduzir ruído e selecionar julgados com aderência ao tema.</div>`)}
function resources(){return wrap(`<div class="hero"><h2>Recursos</h2><p>Fontes jurídicas principais.</p><a class="btn" target="_blank" href="https://www.planalto.gov.br/">Planalto</a><a class="btn" target="_blank" href="https://buscadordizerodireito.com.br/">Dizer o Direito</a><a class="btn" target="_blank" href="https://www.stj.jus.br/sites/portalp/Inicio">STJ</a><a class="btn" target="_blank" href="https://portal.stf.jus.br/">STF</a><a class="btn" target="_blank" href="https://scholar.google.com/">Google Scholar</a></div><div class="notice">Os PDFs Delta não são reproduzidos. A Central registra nome, páginas e tópicos para orientar o estudo do material que você possui.</div>`)}
function answer(n,i){let qs=QUESTIONS[i]||[],q=qs[n];let el=document.querySelector('input[name=q'+n+']:checked'),out=document.getElementById('exp'+n);if(!el){out.textContent='Selecione uma alternativa.';return}let ok=Number(el.value)===q.c;db.checks['q'+i+'_'+n]=ok;saveDB();out.textContent=(ok?'✓ Correto. ':'✗ Incorreto. ')+q.e;out.style.fontWeight='600'}
function show(v){if(v==='week')document.getElementById('content').innerHTML=week();else if(v==='timer')renderTimer();else if(v==='history')renderHistory();else if(v==='perf')document.getElementById('content').innerHTML=perf();else if(v==='search')document.getElementById('content').innerHTML=searchPage();else if(v==='juris')document.getElementById('content').innerHTML=juris();else if(v==='resources')document.getElementById('content').innerHTML=resources();else document.getElementById('content').innerHTML=dashboard();bindChecks()}
show('home');
